all.css:
.pop {
  position: absolute;
  inset: 0;
  background: #f4ead2;
  overflow: hidden;
}

/* Ben-Day dots. One repeating radial-gradient, no image, no animation: a still backdrop keeps
   the glass/blur path cheap and the text underneath crisp. */
.dots {
  position: absolute;
  inset: -20px;
  background-image: radial-gradient(circle, rgba(18,17,13,0.08) 1.5px, transparent 1.9px);
  background-size: 11px 11px;
}

/* Ink outline in the corner of the page, the way a printed panel is bounded. */
.frame {
  position: absolute;
  inset: 14px;
  border: 3px solid rgba(18,17,13,0.55);
}
.frame::after {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid rgba(18,17,13,0.35);
}
/* Flat color wash, one per corner: the Warhol repeat, held low enough to read over. */
.wash {
  position: absolute;
  width: 46vw;
  height: 46vw;
  border-radius: 50%;
  filter: blur(40px);
  opacity: 0.45;
}
.wash.a { top: -14vw; left: -10vw; background: #ffd400; }
.wash.b { bottom: -16vw; right: -8vw; background: #ff2e88; }
.wash.c { top: 30vh; right: 22vw; background: #00b7e0; opacity: 0.28; }

chat.css:
.pop {
  position: absolute;
  inset: 0;
  background: #f7efd9;
  overflow: hidden;
}

/* Ben-Day dots. One repeating radial-gradient, no image, no animation: a still backdrop keeps
   the glass/blur path cheap and the text underneath crisp. */
.dots {
  position: absolute;
  inset: -20px;
  background-image: radial-gradient(circle, rgba(18,17,13,0.08) 1.5px, transparent 1.9px);
  background-size: 11px 11px;
}

/* Halftone: the same dot grid at a larger cell, masked so the dots thin out toward the middle
   where the messages sit. */
.halftone {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, #ff2e88 4px, transparent 4.6px);
  background-size: 22px 22px;
  -webkit-mask-image: radial-gradient(120% 90% at 50% 45%, transparent 40%, #000 100%);
  mask-image: radial-gradient(120% 90% at 50% 45%, transparent 40%, #000 100%);
  opacity: 0.5;
}
.halftone.cyan {
  background-image: radial-gradient(circle, #00b7e0 3px, transparent 3.6px);
  background-size: 22px 22px;
  background-position: 11px 11px;
  opacity: 0.35;
}
/* Speech-bubble tail geometry, blown up and parked behind the column. */
.burst {
  position: absolute;
  top: -18vh;
  left: 50%;
  width: 70vw;
  height: 70vw;
  margin-left: -35vw;
  background: repeating-conic-gradient(from 0deg at 50% 50%, #ffd400 0deg 7deg, transparent 7deg 14deg);
  -webkit-mask-image: radial-gradient(circle at 50% 50%, #000 20%, transparent 62%);
  mask-image: radial-gradient(circle at 50% 50%, #000 20%, transparent 62%);
  opacity: 0.30;
}

write.css:
/* Four flat panels, the silkscreen repeat. Straight lines only: a grid, a gutter, and ink. */
.pop {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 10px;
  padding: 10px;
  background: #12110d;
  overflow: hidden;
}
.panel { position: relative; }
.panel.one { background: #ffd400; }
.panel.two { background: #ff2e88; }
.panel.three { background: #00b7e0; }
.panel.four { background: #ff7a00; }
/* The page reads over the panels, so the color sits under a heavy cream veil. */
.veil {
  position: absolute;
  inset: 0;
  background: #f7efd9;
  opacity: 0.82;
}

/* Ben-Day dots. One repeating radial-gradient, no image, no animation: a still backdrop keeps
   the glass/blur path cheap and the text underneath crisp. */
.dots {
  position: absolute;
  inset: -20px;
  background-image: radial-gradient(circle, rgba(18,17,13,0.08) 1.5px, transparent 1.9px);
  background-size: 11px 11px;
}

.dots { opacity: 0.8; }

